/* Golden vectors for fxHash64 over the first n bytes of
 * "abcdefghijklmnopqrst", n = 0..20. Generated by an independent Python port
 * of the rustc-hash hash_bytes + MCG pipeline; the test only checks frozen
 * values and never reimplements the algorithm. The widening-multiply path and
 * the 32-bit fallback produce different values, so each build checks the set
 * for the path it compiles. */
TEST(FxHashTest, GoldenVectors) {
    static const char input[] = "abcdefghijklmnopqrst";
#if defined(__SIZEOF_INT128__)
    static const uint64_t golden[21] = {
        0xf456d26876d72d91ULL, 0x0bd8e8067b4be2f50ULL, 0x9de70eed801ef68eULL,
        0xe7cfbde76661213fULL, 0x129d90d0160ec9caULL, 0xa34d71fbf6a60d74ULL,
        0x97d77e3209c299faULL, 0x1bf077242562de43ULL, 0x924748ab6aa9dfbdULL,
        0x6befd93faaa65dc3ULL, 0x7f8c835a73d2ca90ULL, 0x9088f7152287323fULL,
        0x40cea97e3da91541ULL, 0x83f0a6de28fdbbccULL, 0x4da40f0f807f8b8cULL,
        0xef89a5f7eda222c6ULL, 0x8fa64e51d6d628a9ULL, 0xd946eb1031217329ULL,
        0xcb519fe94a3a1d07ULL, 0xdc68743e71eed0c9ULL, 0xccdb3d2860891575ULL};
#else
    static const uint64_t golden[21] = {
        0x5a63cfd8888800f6ULL, 0x68178dd2e86ac810ULL, 0x997582aaa4f5de44ULL,
        0xaad37782625ec41cULL, 0xb20420c58fb28f85ULL, 0xffdf3470b886e42cULL,
        0xcadec6a963cf64ccULL, 0xfbf2c7a2b75130ddULL, 0x9dfabeac4c1abe9bULL,
        0x8216a92614b897c9ULL, 0xa67f66bce9268162ULL, 0x9b705716555210caULL,
        0x23bc60792f72206fULL, 0x4bd121e7f45e4ff3ULL, 0xcb1ea696c9bf3aa5ULL,
        0x90c87a7591dd9d8eULL, 0xd126806981371cfcULL, 0xca30baf1b262b8bbULL,
        0x575dd62ad3437c40ULL, 0x613718be8962b6f9ULL, 0x2c34b526c091bf4aULL};
#endif

    for (int len = 0; len <= 20; len++) {
        EXPECT_EQ(fxHash64((const uint8_t *)input, (size_t)len), golden[len])
            << "length " << len;
    }
}

TEST(FxHashTest, EmptyInputAndDeterminism) {
    /* The fixed seeds participate, so the empty string hashes to a fixed
     * non-zero value; folding an empty byte set changes nothing. */
    uint64_t empty = fxHash64((const uint8_t *)"", 0);
    EXPECT_NE(empty, 0ULL);
    EXPECT_EQ(empty, fxHash64Case((const uint8_t *)"", 0));

    const uint8_t *key = (const uint8_t *)"command-name";
    EXPECT_EQ(fxHash64(key, 12), fxHash64(key, 12));
    /* Distinct inputs must not collapse. */
    EXPECT_NE(fxHash64((const uint8_t *)"abc", 3),
              fxHash64((const uint8_t *)"abx", 3));
}

TEST(FxHashTest, CaseFolding) {
    /* All case foldings of the same text hash identically. */
    EXPECT_EQ(fxHash64Case((const uint8_t *)"hello world", 11),
              fxHash64Case((const uint8_t *)"HELLO world", 11));
    EXPECT_EQ(fxHash64Case((const uint8_t *)"hello world", 11),
              fxHash64Case((const uint8_t *)"HELLO WORLD", 11));
    /* The folded value matches the sensitive hash of the lowercased text. */
    EXPECT_EQ(fxHash64Case((const uint8_t *)"GET", 3),
              fxHash64((const uint8_t *)"get", 3));
    /* Sensitive and folded variants stay distinct on uppercase input. */
    EXPECT_NE(fxHash64((const uint8_t *)"GET", 3),
              fxHash64Case((const uint8_t *)"GET", 3));
    /* Bytes outside A-Z pass through unchanged. */
    EXPECT_EQ(fxHash64Case((const uint8_t *)"get-01", 6),
              fxHash64((const uint8_t *)"get-01", 6));
}

/* Reject grossly clustered outputs. Mean occupancy is NUM_KEYS/NUM_BUCKETS
 * (= 4); the thresholds below are unreachable by a degenerate hash but far
 * enough from natural variance to avoid flaky failures. This is the regression
 * guard for low-bit clustering on shared-prefix keys: the rotate-left-26 finish
 * step must move the multiplicative hash's high-entropy top bits into the
 * low bucket-selecting bits (the pre-rotation polynomial collapses here). */
TEST(FxHashTest, DistributionOfInternalStyleKeys) {
    enum { NUM_KEYS = 4096,
           NUM_BUCKETS = 1024 };
    static unsigned char counts[NUM_BUCKETS];
    memset(counts, 0, sizeof(counts));

    char key[32];
    for (int i = 0; i < NUM_KEYS; i++) {
        int len = snprintf(key, sizeof(key), "internal:cmd:%04d", i);
        uint64_t h = fxHash64((const uint8_t *)key, (size_t)len);
        counts[(size_t)(h % NUM_BUCKETS)]++;
    }

    int used_buckets = 0;
    unsigned int max_count = 0;
    for (int i = 0; i < NUM_BUCKETS; i++) {
        if (counts[i] != 0) used_buckets++;
        if (counts[i] > max_count) max_count = counts[i];
    }
    EXPECT_GE(used_buckets, 870); /* at least 85% of the buckets */
    EXPECT_LE(max_count, 16u);    /* no more than 4x the mean */
}

/* The dict wrappers only take the key length and delegate to fxHash, so pin
 * their output to the raw function on the same bytes. */
TEST(FxHashTest, DictWrappersDelegateToFxHash) {
    sds lower = sdsnewlen("get", 3);
    sds upper = sdsnewlen("GET", 3);

    EXPECT_EQ(dictSdsFxHash(lower), fxHash64((const uint8_t *)"get", 3));
    EXPECT_EQ(dictSdsCaseFxHash(upper), fxHash64Case((const uint8_t *)"GET", 3));
    EXPECT_EQ(dictCStrFxHash("get"), fxHash64((const uint8_t *)"get", 3));
    EXPECT_EQ(dictCStrCaseFxHash("GET"), fxHash64Case((const uint8_t *)"GET", 3));

    sdsfree(lower);
    sdsfree(upper);
}

static long long fxBenchUstime(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return ((long long)tv.tv_sec) * 1000000 + tv.tv_usec;
}

/* Manual microbenchmark: run with
 *   ./src/unit/valkey-unit-gtests \
 *       --gtest_filter=FxHashTest.DISABLED_RelativeThroughputVsSipHash \
 *       --gtest_also_run_disabled_tests
 * It prints the relative speedup but never asserts on it. */
TEST(FxHashTest, DISABLED_RelativeThroughputVsSipHash) {
    enum { KEY_LEN = 32,
           PASSES = 1000000 };
    uint8_t key[KEY_LEN];
    uint8_t seed[16];
    int i;
    for (i = 0; i < KEY_LEN; i++) key[i] = (uint8_t)('a' + (i % 26));
    for (i = 0; i < 16; i++) seed[i] = (uint8_t)i;

    uint64_t sink = 0;
    long long start = fxBenchUstime();
    for (i = 0; i < PASSES; i++) sink ^= siphash(key, KEY_LEN, seed);
    long long sip_us = fxBenchUstime() - start;

    start = fxBenchUstime();
    for (i = 0; i < PASSES; i++) sink ^= fxHash64(key, KEY_LEN);
    long long fx_us = fxBenchUstime() - start;

    printf("siphash=%lldus fxhash=%lldus speedup=%.2fx (sink=%llu)\n", sip_us, fx_us,
           (double)sip_us / (double)fx_us, (unsigned long long)sink);
    EXPECT_GT(sip_us, 0LL);
    EXPECT_GT(fx_us, 0LL);
}
